mapper.select:
select
    (select COUNT(*) from Sec_JG_Expert_Audit_Detail ead where ead.Sea_Id=mn.id) as detailCount,
    (select COUNT(*) from Sec_JG_Expert_Audit_Detail ead left join Sec_JG_Expert sje on sje.id=ead.Ex_Id where ead.Sea_Id=mn.id and sje.ex_inside_type=1) as detailInsideCount,
    mn.*
from Sec_JG_Expert_Audit mn

    
        and mn.Te_Id=#{params.teId}
    
    
        and mn.State=#{params.state}
    
    
        and INSTR(mn.Sea_Name,#{params.seaName})
    
    
        and INSTR(mn.Create_Uname,#{params.createUname})
    
    
        and mn.sea_inside_type=#{params.seaInsideType}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc
